<?php
namespace ZCCNG;
if(!defined('ABSPATH'))exit;
final class Permissions{private static $instance;private const MAP=['nexus'=>'zccng_access_nexus','operations'=>'zccng_access_operations','staff'=>'zccng_access_staff_hub','profile'=>'zccng_access_profile','support'=>'zccng_access_support','hr'=>'zccng_access_hr'];public static function instance(){if(!self::$instance)self::$instance=new self();return self::$instance;}public function can($cap){return is_super_admin()||current_user_can($cap);}public function known_workspace($w){return isset(self::MAP[sanitize_key((string)$w)]);}public function workspace($w){$w=sanitize_key((string)$w);return isset(self::MAP[$w])&&$this->can(self::MAP[$w]);}public function require_workspace($w){if(!$this->workspace($w))wp_die(esc_html__('You do not have permission to access this workspace.','zincontrolcenter-nextgen'),403);}public function is_zcc_user(){foreach(array_keys(self::MAP) as $w)if($this->workspace($w))return true;return false;}}
